ST.xhtml:
IF NOT _InitDone THEN
	_InitDone := InitPous();
END_IF


_JobManager.RunJob();


//I/O's connection: Machine -> Material
//For Conveyor:
IO_Simulation.MoverEnable := _Conveyor.MoverEnable;
IO_Simulation.MoverExecuteFor :=  _Conveyor.MoverExecuteFor;
IO_Simulation.MoverExecuteBac :=  _Conveyor.MoverExecuteBac;
// For Robot:
IO_Cobot.Cmd_TargetPos01mm := INT_TO_WORD(_Cobot.MoverTarget);   // 0..5000: no sign issue
IO_Cobot.Cmd_Start := _Cobot.MoverExecute;
IO_Cobot.Cmd_Enable := _Cobot.MoverEnable;
// For Z valve
IO_Simulation.zValve := _zAxis.zValve;
// For Spindle
IO_Simulation.SpindleEnable := _Spindle.SpindleEnable;
IO_Simulation.SpindleExecute := _Spindle.SpindleExecute;
IO_Simulation.SpindleExecuteTime := _Spindle.SpindleExecuteTime;

// Simulation
PRG_PlantSim();

//I/O's connection: Material -> Machine
//For Conveyor:
_Conveyor.MoverActPos := IO_Simulation.MoverActPos;
_Conveyor.MoverReady := IO_Simulation.MoverReady; 
// For cobot:
_Cobot.MoverPosEcho := WORD_TO_INT(IO_Cobot.Sts_TargetPosEcho01mm);
_Cobot.MoverDone := IO_Cobot.Sts_Done;
_Cobot.MoverHeartbeat := WORD_TO_INT(IO_Cobot.Sts_Heartbeat);
// For Z valve
_zAxis.ScrewEngaged := IO_Simulation.ScrewEngaged;
_zAxis.ScrewReleased := IO_Simulation.ScrewReleased;
_zAxis.zDown := IO_Simulation.zDown;
// For Spindle
_Spindle.SpindleReady := IO_Simulation.SpindleReady;
_Spindle.SpindleDone := IO_Simulation.SpindleDone;

// Injection of dependencies
IF Machine_Constants.USE_COBOT THEN
	_Mover := _Cobot;
ELSE
	_Mover := _Conveyor;
END_IF

_ReportJob.AddSink(_LogSink);

InitPous := _JobManager.Init(
	UserInterface := _UserInterface,
	JobSelector := _JobSelector,
	Mover:= _Mover,
	zAxis := _zAxis,
	Spindle := _Spindle,
	ReportJob := _ReportJob);

RaiseError := FALSE;

IF _Error = ErrorCode.NoError THEN
	_Error := Error;
	Trace(CmpLog.LogClass.LOG_ERROR, ErrorCodeToString(Error));
	RaiseError := TRUE;
END_IF

IF NOT _InitDone THEN
	RETURN;
END_IF

_ActiveError := CheckErrors();
_Stop := _UserInterface.IsStopRequired();

IF _ActiveError <> ErrorCode.NoError AND _state <> JobState.Reset THEN
    _state := JobState.Error;
END_IF

IF _state <> JobState.Reset AND _state <> JobState.Error THEN
    EnableAll();
ELSE
    DisableAll();
END_IF

CASE _state OF
	JobState.Reset :
		IF ResetAll() THEN
			_state := JobState.Idle;
		END_IF
	JobState.Idle:
		IF _Stop THEN
			_state := JobState.Reset;
		ELSIF _zAxis.Retract() THEN
        	IF _UserInterface.IsStartRequired() THEN
            _ReportJob.Reset();
			_ReportJob.JobStart();
            _state := JobState.ReadingTargetPosition;
        	END_IF
    	END_IF
	JobState.ReadingTargetPosition :
		IF _JobSelector.ReturnScrew() THEN
			_state:= JobState.MovingToTargetPosition;
		ELSE
			_state := JobState.MovingToBase;
		END_IF
	JobState.MovingToTargetPosition :
		IF _Mover.MoveToPosition(_JobSelector.CurrentScrew.PositionMm) THEN
			_state:= JobState.MovingZaxisToTool;
		END_IF
	JobState.MovingZaxisToTool :
		    CASE _zAxis.Engage() OF
        		ActionResult.Done:
            		_state := JobState.ProcessingTool;
				ActionResult.Failed:
            		_ReportJob.FailScrew(_JobSelector.CurrentScrew);
					_state := JobState.MovingZaxisToBase;
    		END_CASE
	JobState.ProcessingTool :
		IF _Spindle.ProcessTool(_JobSelector.CurrentScrew.AngleDeg) THEN		
			_ReportJob.SuccessScrew(_JobSelector.CurrentScrew);
			_state:= JobState.MovingZaxisToBase;
		END_IF
	JobState.MovingZaxisToBase :
		IF _zAxis.Retract() THEN
			_state:= JobState.ReadingTargetPosition;
		END_IF
	JobState.MovingToBase :
		IF _Mover.MoveToPosition(0)  THEN
			_state := JobState.Idle;
			_ReportJob.JobEnd();
		END_IF
	JobState.Error :
		IF _Stop THEN
			_state := JobState.Reset;
		END_IF
END_CASE

// Stop during a job = abort: publish the partial report, then reset every component.
// The next Start begins a fresh job from the first screw.
IF _Stop
   AND _state <> JobState.Idle
   AND _state <> JobState.Reset
   AND _state <> JobState.Error THEN
	_ReportJob.JobAborted();
	_state := JobState.Reset;
END_IF

_UserInterface REF= UserInterface;
_JobSelector REF= JobSelector;
_Mover := Mover;
_zAxis REF= zAxis;
_Spindle REF= Spindle;
_ReportJob REF= ReportJob;

// Reseters
_Reseters[1] := _UserInterface;
_Reseters[2] := _JobSelector;
_Reseters[3] := _Mover;
_Reseters[4] := _zAxis;
_Reseters[5] := _Spindle;
_Reseters[6] := _ReportJob;

// Diagnosable
_Diagnosable[1] := _UserInterface;
_Diagnosable[2] := _JobSelector;
_Diagnosable[3] := _Mover;
_Diagnosable[4] := _zAxis;
_Diagnosable[5] := _Spindle;
_Diagnosable[6] := _ReportJob;

_InitDone := TRUE;
Init := TRUE;

_SpindleOk := _Spindle.Disable();
_MoverOk   := _Mover.Disable();
DisableAll := _SpindleOk AND _MoverOk;

_SpindleOk := _Spindle.Enable();
_MoverOk   := _Mover.Enable();
EnableAll  := _SpindleOk AND _MoverOk;

ResetAll := TRUE;

FOR _i := 1 TO UPPER_BOUND(_Reseters, 1) DO
    IF NOT _Reseters[_i].Reset() THEN
        ResetAll := FALSE;
    END_IF
END_FOR

ClearError();
_TableIndex := 0;
Job_Done := FALSE;

Reset := TRUE;

ReturnScrew := FALSE;


IF SelectNextScrew() THEN
	CurrentScrew := ArrScrews[_TableIndex];
	ReturnScrew := TRUE;
ELSE
	CurrentScrew.PositionMm := 0.0;
	CurrentScrew.AngleDeg := 0;
END_IF

// Method responsible for incrementing _TableIndex
SelectNextScrew := FALSE;
Job_Done := FALSE;
IF _TableIndex < UPPER_BOUND(ArrScrews, 1) THEN
	_TableIndex := _TableIndex + 1;
	SelectNextScrew := TRUE;
ELSE
	_TableIndex := 0;
	Job_Done := TRUE;
END_IF

ClearError();
Disable();
MoverExecuteFor := FALSE;
MoverExecuteBac := FALSE;
_MoverTarget :=  0.0;
_TimerEnablement(IN := FALSE, PT := T#1S);
_TimerMoveLinear(IN := FALSE, PT := T#100S);
Reset := TRUE;

MoveToPosition := FALSE;

_MoverTarget := Position;


IF _TimerMoveLinear.Q THEN
	RaiseError(ErrorCode.TargetNotReached);
ELSIF _MoverTarget - MoverActPos >= 1 THEN
	MoverExecuteFor := TRUE;
ELSIF _MoverTarget - MoverActPos <= -1 THEN
	MoverExecuteBac := TRUE;
ELSE
	MoveToPosition := TRUE;
	MoverExecuteFor := FALSE;
	MoverExecuteBac := FALSE;
END_IF

_TimerMoveLinear(IN := (MoverExecuteFor OR MoverExecuteBac), PT := T#100S);

Enable := FALSE;

MoverEnable := TRUE;
_TimerEnablement(IN := MoverEnable AND NOT MoverReady, PT := T#1S);

IF MoverReady THEN
	Enable := TRUE;
ELSIF _TimerEnablement.Q THEN
	RaiseError(ErrorCode.EnablementError);
END_IF

ClearError();

zValve := FALSE;

IF zDown THEN
	Reset := TRUE;
END_IF

_timerUp(IN := FALSE, PT := T#5S);
_timerDown(IN := FALSE, PT := T#5S);

Engage := ActionResult.Busy;
zValve := TRUE;

_timerUp(IN := zValve AND NOT ScrewEngaged, PT := T#5S);
_timerDown(IN := FALSE, PT := T#5S);

IF ScrewEngaged THEN
	Engage := ActionResult.Done;
ELSIF _timerUp.Q THEN
	Engage := ActionResult.Failed;
END_IF

Retract := FALSE;
zValve := FALSE;

_timerDown(IN := NOT zValve AND NOT (zDown AND ScrewReleased), PT := T#5S);
_timerUp(IN := FALSE, PT := T#5S);

IF zDown AND ScrewReleased THEN
    Retract := TRUE;
ELSIF _timerDown.Q THEN
	RaiseError(ErrorCode.ScrewNotReleased);
END_IF

ClearError();
Disable();
SpindleEnable := FALSE;
SpindleExecute := FALSE;
SpindleExecuteTime := T#0S;
_AngleTarget := 0;
_Started := FALSE;
_TimerEnablement(IN := FALSE, PT := T#1S);
_TimerProcessTool(IN := FALSE, PT := T#20S);
Reset := TRUE;

ProcessTool := FALSE;
_TimerProcessTool(IN := SpindleExecute AND NOT SpindleDone, PT := T#20S);
_AngleTarget := ABS(Angle); 

IF NOT _Started AND SpindleEnable THEN
	SpindleExecuteTime := DINT_TO_TIME(_AngleTarget*1000/SpeedDegPerSec);
	SpindleExecute := TRUE;
	_Started := TRUE;
ELSIF SpindleDone THEN
	SpindleExecute := FALSE;
	_Started := FALSE;
	ProcessTool := TRUE;
ELSIF _TimerProcessTool.Q THEN
	RaiseError(ErrorCode.SpindleError);
END_IF

Enable := FALSE;

SpindleEnable := TRUE;
_TimerEnablement(IN := SpindleEnable AND NOT SpindleReady, PT := T#1S);

IF SpindleReady THEN
	Enable := TRUE;
ELSIF _TimerEnablement.Q THEN
	RaiseError(ErrorCode.EnablementError);
END_IF

// Conveyor
IO_Simulation.MoverReady := IO_Simulation.MoverEnable
                                   AND NOT IO_Simulation.SimFail_MoverReady;
IF IO_Simulation.MoverExecuteFor AND IO_Simulation.MoverEnable
   AND NOT IO_Simulation.SimFail_MoverBlocked THEN
    IO_Simulation.MoverActPos := IO_Simulation.MoverActPos + _Increment;
ELSIF IO_Simulation.MoverExecuteBac AND IO_Simulation.MoverEnable
   AND NOT IO_Simulation.SimFail_MoverBlocked THEN
    IO_Simulation.MoverActPos := IO_Simulation.MoverActPos - _Increment;
END_IF

// Z Axis
_ZAxisMovingTimeUp(IN := IO_Simulation.zValve, PT := T#1S);
IO_Simulation.ScrewEngaged := _ZAxisMovingTimeUp.Q
                                     AND NOT IO_Simulation.SimFail_ScrewEngaged;
_ZAxisMovingTimeDown(IN := NOT IO_Simulation.zValve, PT := T#1S);
IO_Simulation.ScrewReleased := _ZAxisMovingTimeDown.Q
                                      AND NOT IO_Simulation.SimFail_ScrewReleased;
// zDown is not filtered: the cylinder physically retracts even if the bit stays engaged
IO_Simulation.zDown := _ZAxisMovingTimeDown.Q;

// Spindle
IO_Simulation.SpindleReady := IO_Simulation.SpindleEnable;
_SpindleMovingTime(IN := IO_Simulation.SpindleExecute
                         AND IO_Simulation.SpindleEnable,
                   PT := IO_Simulation.SpindleExecuteTime);
IO_Simulation.SpindleDone := _SpindleMovingTime.Q
                                    AND NOT IO_Simulation.SimFail_SpindleDone;

ClearError();
_NbSuccess := 0;
_NbFail := 0;
_JobDone := FALSE;

_FailedScrews     := _EmptyScrewList;
_SuccessfulScrews := _EmptyScrewList;

Reset := TRUE;

_FinishedAt := Now();

Trace(CmpLog.LogClass.LOG_INFO, 'Job Done');

JobEnd := SendReportToSinks(Completed := TRUE);

SuccessScrew := FALSE;

IF _NbSuccess < UPPER_BOUND(_SuccessfulScrews, 1) THEN
	_NbSuccess := _NbSuccess + 1;
	_SuccessfulScrews[_NbSuccess] := SuccessfulScrew;
	SuccessScrew := TRUE;
END_IF

Trace(CmpLog.LogClass.LOG_INFO,
        CONCAT('Screw successfully processed at position ', REAL_TO_STRING(SuccessfulScrew.PositionMm)));

FailScrew := FALSE;

IF _NbFail < UPPER_BOUND(_FailedScrews, 1) THEN
	_NbFail := _NbFail + 1;
	_FailedScrews[_NbFail] := FailedScrew;
	FailScrew := TRUE;
END_IF

Trace(CmpLog.LogClass.LOG_WARNING,
        CONCAT('Screw missed at position ', REAL_TO_STRING(FailedScrew.PositionMm)));

_JobId      := _JobId + 1;
_StartedAt  := Now();
_FinishedAt := DT#1970-01-01-00:00:00;

Trace(CmpLog.LogClass.LOG_INFO, 'Job Started');

JobStart := TRUE;

_FinishedAt := Now();

Trace(CmpLog.LogClass.LOG_WARNING, 'Job Aborted');

JobAborted := SendReportToSinks(Completed := FALSE);

AddSink := FALSE;

FOR _i := 1 TO UPPER_BOUND(_Sinks, 1) DO
	IF _Sinks[_i] = 0 THEN
		_Sinks[_i] := Sink;
		AddSink := TRUE;
		RETURN;
	END_IF
END_FOR

_report.JobId        := _JobId;
_report.StartedAt    := _StartedAt;
_report.FinishedAt   := _FinishedAt;
_report.ScrewsOk     := _NbSuccess;
_report.ScrewsFailed := _NbFail;
_report.FailedScrews := _FailedScrews;
_report.Completed := Completed;

SendReportToSinks := TRUE;

FOR _i := 1 TO UPPER_BOUND(_Sinks, 1) DO
	IF _Sinks[_i] <> 0 THEN
		IF NOT _Sinks[_i].PublishReport(_report) THEN
			SendReportToSinks := FALSE;
		END_IF
	END_IF
END_FOR

_sec := SysTimeRtcGet(_res);

IF _res = Errors.ERR_OK THEN
	Now := UDINT_TO_DT(_sec);
ELSE
	Now := DT#1970-01-01-00:00:00;
	RaiseError(ErrorCode.RtcNotAvailable);
END_IF

CASE Code OF
	ErrorCode.NoError :
		ErrorCodeToString := 'No Error';
	ErrorCode.EnablementError:
		ErrorCodeToString := 'Enablement Error';
	ErrorCode.ScrewNotReleased:
		ErrorCodeToString := 'Screw Not Released';
	ErrorCode.TargetNotReached:
		ErrorCodeToString := 'Target Not Reached';
	ErrorCode.SpindleError:
		ErrorCodeToString := 'Spindle Error';
	ErrorCode.CobotNotConnected:
		ErrorCodeToString := 'Cobot Not Connected';
	ErrorCode.CobotMovementNotReached:
		ErrorCodeToString := 'Cobot Movement Not Reached';
	ErrorCode.RtcNotAvailable:
		ErrorCodeToString := 'Rtc Not Available';
ELSE
		ErrorCodeToString := 'Unknown Error';	
END_CASE

ClearError();
Disable();
MoverTarget :=  0;
_state := MoverState.Idle;
_TimerEnablement(IN := FALSE, PT := T#1S);
_TimerEcho(IN := FALSE, PT := T#2S);
_TimerMove(IN := FALSE, PT := T#30S);
_HbTimer(IN := FALSE, PT := T#500MS);

Reset := TRUE;

MoveToPosition := FALSE;

CASE _state OF

	MoverState.Idle:
		// Never start a cycle while the robot still asserts Done from a previous one
		IF NOT MoverDone THEN
			MoverTarget  := REAL_TO_INT(Position * 10.0);
			MoverExecute := FALSE;
			_state := MoverState.WaitingEcho;
		END_IF

	MoverState.WaitingEcho:
		IF MoverPosEcho = MoverTarget THEN
			MoverExecute := TRUE;
			_state := MoverState.Moving;
		ELSIF _TimerEcho.Q THEN
			RaiseError(ErrorCode.CobotNotConnected);
		END_IF

	MoverState.Moving:
		IF MoverDone THEN
			MoverExecute := FALSE;
			_state := MoverState.WaitingDoneReleased;
		ELSIF _TimerMove.Q THEN
			RaiseError(ErrorCode.CobotMovementNotReached);
		END_IF

	MoverState.WaitingDoneReleased:
		IF NOT MoverDone THEN
			MoveToPosition := TRUE;
			_state := MoverState.Idle;
		END_IF

END_CASE

_TimerEcho(IN := (_state = MoverState.WaitingEcho), PT := T#2S);
_TimerMove(IN := (_state = MoverState.Moving), PT := T#30S);

_HbChanged := (MoverHeartbeat <> _LastHeartbeat);
_LastHeartbeat := MoverHeartbeat;
_HbTimer(IN := NOT _HbChanged, PT := T#500MS);
_Alive := NOT _HbTimer.Q;

Enable := FALSE;
MoverEnable := TRUE;

_TimerEnablement(IN := NOT _Alive, PT := T#1S);

IF _Alive THEN
	Enable := TRUE;
ELSIF _TimerEnablement.Q THEN
	RaiseError(ErrorCode.CobotNotConnected);
END_IF

MoverEnable  := FALSE;
MoverExecute := FALSE;
Disable := TRUE;

_msg := CONCAT('Job ', UDINT_TO_STRING(Report.JobId));
_msg := CONCAT(_msg,   ' finished: ');
_msg := CONCAT(_msg,   INT_TO_STRING(Report.ScrewsOk));
_msg := CONCAT(_msg,   ' ok, ');
_msg := CONCAT(_msg,   INT_TO_STRING(Report.ScrewsFailed));
_msg := CONCAT(_msg,   ' failed');

Trace(CmpLog.LogClass.LOG_INFO, _msg);

PublishReport := TRUE;

LogAdd(
	hLogger   := CmpLog.LogConstants.LOG_STD_LOGGER,
	stCmpName := Machine_Constants.LOG_COMPONENT_NAME,
	diClassID := UDINT_TO_DINT(Severity),
	diErrorID := 0,
	diInfoID  := 0,
	stInfo    := Msg
);

Trace := TRUE;
